// Cloudflare Pages worker (advanced mode), in front of the static files of the docs. _routes.json keeps the
// assets out of it. https://developers.cloudflare.com/pages/functions/advanced-mode/

// Resources of the homepage for the agents (RFC 8288), the agents do not parse the HTML to find them
const HOME_LINKS = [
  '</llms.txt>; rel="describedby"; type="text/plain"',
  '</llms.txt>; rel="alternate"; type="text/markdown"',
  '</guide/getting-started>; rel="service-doc"',
]

// The .md version of a page, generated by vitepress-plugin-llms: /guide/bump -> /guide/bump.md,
// /commitlint/ -> /commitlint.md. The homepage has none: llms.txt, the markdown index of the docs, stands for it
function getMarkdownPath(pathname) {
  const path = pathname.replace(/\/$/, '')

  return path === '' ? '/llms.txt' : `${path}.md`
}

function wantsMarkdown(request) {
  return ['GET', 'HEAD'].includes(request.method) && /\btext\/markdown\b/.test(request.headers.get('Accept') ?? '')
}

function withHeaders(response, headers) {
  const result = new Response(response.body, response)

  for (const [name, value] of Object.entries(headers)) {
    result.headers.append(name, value)
  }

  return result
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url)

    // Markdown for the agents that ask for it (Accept: text/markdown), the HTML stays the default
    if (wantsMarkdown(request)) {
      const markdown = await env.ASSETS.fetch(new Request(new URL(getMarkdownPath(url.pathname), url), request))

      if (markdown.ok) {
        const response = withHeaders(markdown, { Vary: 'Accept' })
        response.headers.set('Content-Type', 'text/markdown; charset=utf-8')

        return response
      }
    }

    const response = await env.ASSETS.fetch(request)

    return withHeaders(response, url.pathname === '/'
      ? { Vary: 'Accept', Link: HOME_LINKS.join(', ') }
      : { Vary: 'Accept' })
  },
}
